-- Foreign keys for the reconstructed UniTour tables (extracted from the real UniTour source).
-- PostgREST needs these for embedded joins like agent_referrals(booking:bookings(...)).
ALTER TABLE public.tours ADD CONSTRAINT fk_tours_destination_id FOREIGN KEY ("destination_id") REFERENCES public.destinations(id) ON DELETE SET NULL;
